// Two tests: built-in dev fixture + real-style case_file passed by the parent.
const realistic = {
  prescription: {exercise:'elbow_flexion', target_reps:5, target_rom:100},
  metrics: {reps_vs_target_pct:60, rom_vs_target_pct:80, fault_counts:{TRUNK_LEAN:2},
            fast_rep_share:0, rom_slope_deg_per_session:null, baseline_rom:null,
            quality_band:'fair', incomplete_attempts:0, sessions_in_history:0},
  rule_flags:[{code:'LOW_COMPLETION',severity:'medium',source:'rule',evidence:'Synthetic test flag'}],
  session:{session_id:101, exercise:'elbow_flexion',total_reps:3,mean_rom:80,mean_quality:0.60,reps:[]},
  history:[]
};
return [{json:{}}, {json:{case_file:realistic}}];

return $input.all().map((item, i) => {
  const x = item.json || {}, m = x.metrics || {}, f = Array.isArray(x.rule_flags) ? x.rule_flags : [];
  let name = 'unexpected-case', pass = false;
  if (m.reps_vs_target_pct === 100) {
    name = 'get_case_file / built-in dev fixture';
    pass = x.prescription?.target_reps === 10 && m.fault_counts?.SHOULDER_HIKE === 3
           && f.some(z => z.code === 'ROM_DROP' && z.severity === 'high') && !('reps' in x);
  } else if (m.reps_vs_target_pct === 60) {
    name = 'get_case_file / supplied case file';
    pass = x.prescription?.target_reps === 5 && m.fault_counts?.TRUNK_LEAN === 2
           && f.some(z => z.code === 'LOW_COMPLETION') && !('reps' in x);
  }
  return {json:{tool:'get_case_file',test:name,pass,output:x}};
});

// Four calls, one per input item (Execute Sub-workflow mode = each).
const realistic = {
  prescription:{exercise:'elbow_flexion',target_reps:5,target_rom:100},
  metrics:{fault_counts:{TRUNK_LEAN:1}}, rule_flags:[], history:[],
  session:{session_id:101,exercise:'elbow_flexion',reps:[
    {rep_number:1,max_angle:120,min_angle:30,rom:90,duration_s:2.0,quality_score:0.8,faults:[{code:'TRUNK_LEAN'}]}
  ]}
};
return [
  {json:{rep_number:8}},
  {json:{rep_number:2}},
  {json:{rep_number:99}},
  {json:{rep_number:1,case_file:realistic}},
];

return $input.all().map(item => {
  const x = item.json || {};
  let name = 'unexpected-rep', pass = false;
  if (x.found === true && x.rep_number === 8) {
    name = 'get_rep_details / rep 8 SHOULDER_HIKE';
    pass = x.faults?.includes('SHOULDER_HIKE') && x.duration_s === 2.1;
  } else if (x.found === true && x.rep_number === 2) {
    name = 'get_rep_details / rep 2 clean';
    pass = Array.isArray(x.faults) && x.faults.length === 0;
  } else if (x.found === false && Number(x.rep_number) === 99) {
    name = 'get_rep_details / rep 99 missing';
    pass = x.available_rep_numbers?.length === 10 && x.available_rep_numbers.includes(8);
  } else if (x.found === true && x.rep_number === 1 && x.rom === 90) {
    name = 'get_rep_details / supplied case file';
    pass = x.faults?.includes('TRUNK_LEAN') && x.min_angle === 30 && x.max_angle === 120;
  }
  return {json:{tool:'get_rep_details',test:name,pass:!!pass,output:x}};
});

// Three calls: new fault, absent fault, and a historical fault with a supplied real-style case file.
const realistic = {
  prescription:{exercise:'elbow_flexion',target_reps:5,target_rom:100},
  metrics:{fault_counts:{TRUNK_LEAN:1}}, rule_flags:[],
  session:{session_id:101,exercise:'elbow_flexion',reps:[]},
  history:[
    {session_id:100,date:'2026-11-17',fault_counts:{TRUNK_LEAN:2}},
    {session_id:99,date:'2026-11-15',fault_counts:{TRUNK_LEAN:1}},
  ]
};
return [
  {json:{fault_code:'SHOULDER_HIKE'}},
  {json:{fault_code:'TOO_FAST'}},
  {json:{fault_code:'TRUNK_LEAN',case_file:realistic}},
];

return $input.all().map(item => {
  const x = item.json || {};
  let name = 'unexpected-fault', pass = false;
  if (x.fault_code === 'SHOULDER_HIKE') {
    name = 'get_fault_history / new SHOULDER_HIKE';
    pass = x.current_session_count === 3 && x.total_in_history === 0
           && x.is_new_this_session === true && x.seen_in_history === false;
  } else if (x.fault_code === 'TOO_FAST') {
    name = 'get_fault_history / absent TOO_FAST';
    pass = x.current_session_count === 0 && x.total_in_history === 0
           && x.is_new_this_session === false;
  } else if (x.fault_code === 'TRUNK_LEAN') {
    name = 'get_fault_history / supplied historical TRUNK_LEAN';
    pass = x.current_session_count === 1 && x.total_in_history === 3
           && x.seen_in_history === true && x.is_new_this_session === false
           && x.history?.length === 2;
  }
  return {json:{tool:'get_fault_history',test:name,pass:!!pass,output:x}};
});

const tests = $input.all().map(item => item.json);
const passed = tests.filter(x => x.pass === true).length;
const failed = tests.filter(x => x.pass !== true).length;
return [{json:{
  status: failed === 0 && tests.length === 9 ? 'PASS' : 'FAIL',
  passed, failed, total: tests.length, expected_total: 9,
  note: 'These checks execute the SELECTED published A2 sub-workflows; no LLM or patient data is needed.',
  results: tests.map(({tool,test,pass,output}) => ({tool,test,pass,output})),
}}];
